source.exploreUrl:
@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});


	push('推荐', `/app/api/book/newest?page={{page}}&limit=20`, 1, 1);
	 tj=[["热门","index"],["最新","newest"]];
		tj.map([title,uri]=>{
	    url= `/app/api/album/${uri}?type=3&page={{page}}&limit=20`;
			 	push(title, url, 1, 0.25);     	
	});

	fl =	[
	 ["男频",
	[["玄幻奇幻","3"],["恐怖灵异","4"],["武侠修真","8"],["乡村生活","9"],["历史军事","11"],["科幻末世","12"],["游戏竞技","16"],["都市小说","21"]]],
  	["女频",
	[["都市言情","5"],["古代言情","6"],["浪漫青春","7"],["二次元","17"]]],
	 ["综合",
	[["现代文学","14"],["古典文学","15"],["外国文学","22"],["侦探推理","23"]]]
	];
//sort=1最新 2最热 3字数 4章数
	fl.map([title,list]=>{			
		push(title, null, 1, 1);
	   list.map([title,cid]=>{ 	
	   	url=`/app/api/book/list?cid=${cid}&size=0&sort=1&page={{page}}&limit=20`;     
				push(title, url, 0.25); 
				});
	});

JSON.stringify(sort);

